#!/usr/bin/env node
//
// Bump the site version for a production release.
//
// Scheme: 1.<mmdd>.<previous patch + 1>
//   - major  stays 1
//   - minor  is the release date as zero-padded month+day (Asia/Jerusalem, the
//            timezone the rest of the fleet stamps its builds in)
//   - patch  is a monotonic counter: previous patch + 1, so it always advances
//            even when the day (and therefore the minor) rolls over
//
// package.json is the single source of truth for the version. The deploy
// workflow runs this, then commits the bumped file back to main — so the number
// in the repo always names the last release that actually went out.
//
// Prints the new version to stdout (nothing else) so the workflow can capture it.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const pkgPath = join(dirname(fileURLToPath(import.meta.url)), "..", "package.json");
const pkg = JSON.parse(readFileSync(pkgPath, "utf8"));

// The current patch is the third dotted component; treat anything unparseable
// (e.g. the initial "1.0.0") as 0 so the first bump lands on patch 1.
const prevPatch = Number.parseInt(String(pkg.version ?? "").split(".")[2], 10);
const newPatch = (Number.isFinite(prevPatch) ? prevPatch : 0) + 1;

const parts = new Intl.DateTimeFormat("en-CA", {
  timeZone: "Asia/Jerusalem", month: "2-digit", day: "2-digit",
}).formatToParts(new Date());
const mm = parts.find((p) => p.type === "month").value;
const dd = parts.find((p) => p.type === "day").value;

const newVersion = `1.${mm}${dd}.${newPatch}`;
pkg.version = newVersion;
writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + "\n");

console.log(newVersion);

// Cloudflare Web Analytics — privacy-first, cookieless visitor counts.
//
// Cloudflare Web Analytics sets no cookies, stores no personal data, and can't
// track visitors across sites, so it needs no consent banner (see privacy.html).
//
// The beacon token is NOT a secret — it ships in the client and is visible to
// every visitor — so it lives in a GitHub Actions *variable* (not a secret):
//   repo Settings -> Secrets and variables -> Actions -> Variables ->
//   CLOUDFLARE_ANALYTICS_TOKEN
// The Pages deploy (.github/workflows/deploy-pages.yml) injects that value into
// the placeholder below at build time.
//
// TO ENABLE: create a free site in the Cloudflare dashboard (Web Analytics ->
// "Add a site"), then add its token as the CLOUDFLARE_ANALYTICS_TOKEN repo variable.
// It works on GitHub Pages as-is — no hosting or DNS move to Cloudflare needed.
//
// Until a real token is injected (variable unset, or running locally), this
// loader does nothing: no beacon is requested, so the site keeps its "no
// analytics" behaviour and never ships a broken tag.
(function () {
  var TOKEN = 'REPLACE_WITH_CLOUDFLARE_WEB_ANALYTICS_TOKEN';
  // Bail out while the placeholder is still in place (startsWith, ES5-safe).
  if (!TOKEN || TOKEN.lastIndexOf('REPLACE_WITH', 0) === 0) return;

  var beacon = document.createElement('script');
  beacon.defer = true;
  beacon.src = 'https://static.cloudflareinsights.com/beacon.min.js';
  beacon.setAttribute('data-cf-beacon', JSON.stringify({ token: TOKEN }));
  (document.head || document.documentElement).appendChild(beacon);
})();

